-- Lanyard — post-migration setup script.
-- Run this in the Supabase SQL Editor AFTER applying ALL migration files:
--   0001_init.sql, 0002_rep_current_conference.sql, 0003_coverage_suggestions.sql
-- 1. Creates the private recordings bucket
-- 2. Seeds conference data (real fintech events)
-- 3. Seeds your rep row (fill in YOUR_AUTH_USER_ID below)

-- ── 1. Storage bucket ────────────────────────────────────────────────────────
values ('recordings', 'recordings', false)
on conflict (id) do nothing;

-- ── 2. Conference seed data (T2) ─────────────────────────────────────────────
-- 44 REAL events (researched from public info: dates, location, audience) spanning
-- fintech, payments, treasury/FX, cross-border, travel, and SaaS. icp_score/tier/score_breakdown
-- are the C4 engine output (AI-estimated factors → weighted formula); baked in so a fresh DB is
-- fully scored without an API key. "Re-score with AI" / Discover refresh them live.
-- Regenerate this block from the DB with: node scripts/gen-conference-seed.mjs
on conflict do nothing;

-- ── 3. Your rep row ───────────────────────────────────────────────────────────
-- Replace YOUR_AUTH_USER_ID with the User UID from Authentication → Users in your Supabase dashboard.
-- Replace name/email with your details.
values (
  'YOUR_AUTH_USER_ID',
  'Your Name',
  'your@email.com',
  '00000000-0000-0000-0000-000000000001'
)
on conflict (auth_user_id) do nothing;

-- ── 4. Teammate reps (the wider sales team; no auth account — for coverage planning) ──
-- home_city/region/lat/lng + capacity added by 0003_coverage_suggestions migration.
on conflict (id) do nothing;

-- ── 5. Conference coverage (who covers what; deliberate gaps + clusters for the demo) ──
